func (a *App) handleContextSwitchComplete(msg ContextSwitchCompleteMsg) (tea.Model, tea.Cmd) {
	a.switchingTo = ""
	a.config = msg.Config
	a.currentContext = msg.ContextName
	theme.SetGaugeGlyph(msg.Config.App.GaugeGlyph)
	a.sharedState.Secrets = msg.Secrets
	a.sharedState.SecretNotices = msg.Notices

	// Reset GitLab auth state — the new context has its own credentials
	a.clearAuthenticated()

	// Apply auto-login result from the context switch if successful
	var indexCmd tea.Cmd
	if msg.Forge != nil {
		indexCmd = a.setAuthenticated(msg.Forge, msg.GitLabUser)
	} else {
		// No credentials available — navigate to auth view for manual login
		a.currentView = command.ViewGitAuth
	}

	// The new context's tools may run from elsewhere: its views start from
	// "not known yet" rather than from the previous context's answer.
	a.forgetScanTools()

	// Reinitialize views with new config; auth state is already populated above
	initCmd := a.reinitializeViews()

	// The rebuilt views know nothing of the work that is still running, and it
	// did not stop: a run is stamped with the context it was started in and
	// kept for the session (D8), so a switch changes which runs are relevant,
	// never whether they exist. Telling the new views is the whole of it.
	return a, tea.Batch(a.requestResize(), initCmd, a.jobsChanged(), a.restartMCPCmd(), a.syncProxyPortCmd(),
		a.detectScanTools(), indexCmd)
}

// handleContextList opens the picker with the cursor on the context in use, so
// enter is a no-op rather than a switch to whatever sorts first.
func (a *App) handleContextList(msg ContextListMsg) (tea.Model, tea.Cmd) {
	a.showContextList = true
	a.contextList = msg.Contexts
	a.contextSelectedIdx = indexOf(msg.Contexts, msg.Current)
	return a, nil
}

// handleContextListKeyMsg handles key presses in the context selection overlay
func (a *App) handleContextListKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc", "q":
		a.showContextList = false
	case "up":
		a.contextSelectedIdx = max(a.contextSelectedIdx-1, 0)
	case "down":
		a.contextSelectedIdx = min(a.contextSelectedIdx+1, len(a.contextList)-1)
	case "enter":
		if len(a.contextList) > 0 {
			a.showContextList = false
			return a, a.switchContext(a.contextList[a.contextSelectedIdx])
		}
	}
	return a, nil
}

// renderContextListOverlay renders an overlay with the list of contexts
func (a *App) renderContextListOverlay() string {
	return renderPickerOverlay("Select Context", a.contextList, a.currentContext, a.contextSelectedIdx)
}

// renderContextSwitchingOverlay stands in for the interface while a switch
// loads, so the first views drawn after it are the new context's.
func (a *App) renderContextSwitchingOverlay() string {
	return theme.OverlayBoxStyle().Render(theme.Bg("Switching to context " + a.switchingTo + "..."))
}

// renderPickerOverlay draws the list overlays: a title, one entry per line, the
// entry in use marked and the highlighted one carrying the focus indicator.
func renderPickerOverlay(title string, entries []string, current string, selectedIdx int) string {
	var b strings.Builder

	b.WriteString(theme.TitleStyle.Render(title) + "\n\n")

	for i, entry := range entries {
		label := entry
		if entry == current {
			label += " (current)"
		}
		if i == selectedIdx {
			b.WriteString(theme.KeyStyle.Render(theme.IconCircleSmall + " " + label))
		} else {
			b.WriteString(theme.Bg("  " + label))
		}
		b.WriteString("\n")
	}

	return theme.OverlayBoxStyle().Render(b.String())
}

// indexOf returns the position of want, or 0 when it is absent — the cursor has
// to land on a row that exists.
func indexOf(entries []string, want string) int {
	for i, entry := range entries {
		if entry == want {
			return i
		}
	}
	return 0
}
package app

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/contextcmd"
	"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// argStage reports whether the list shows argument rows: the :ctx command at
// its argument stage. Other commands keep the single command row.
func (a *App) argStage() bool {
	return a.suggestions.Stage == command.StageArgument &&
		command.ParseCommand(a.commandInput.Value()).Type == command.CommandContext
}

// listRowCount is how many rows the list holds at the current stage.
func (a *App) listRowCount() int {
	if a.argStage() {
		return len(a.suggestions.Args)
	}
	return len(a.suggestions.Entries)
}

// ctxArgText is the text typed after the command word, trimmed on the left.
func (a *App) ctxArgText() string {
	_, rest, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
	return strings.TrimLeft(rest, " ")
}

// defaultArgCursor picks the row highlighted when the argument list is drawn:
// the exact match; else the only match when contextcmd accepts it as a valid
// name; else none.
func (a *App) defaultArgCursor() int {
	args := a.suggestions.Args
	prefix := a.ctxArgText()
	if prefix == "" || !a.suggestions.ArgsReady {
		return -1
	}
	for i, s := range args {
		if s.Value == prefix {
			return i
		}
	}
	if len(args) != 1 {
		return -1
	}
	if !validContextText(prefix) {
		return -1
	}
	return 0
}

// validContextText reports whether s is made of lowercase letters, digits and
// hyphens, the characters a context name may hold.
func validContextText(s string) bool {
	for _, r := range s {
		if (r < 'a' || r > 'z') && (r < '0' || r > '9') && r != '-' {
			return false
		}
	}
	return s != ""
}

// argHeading is the rule's label at the argument stage: contexts shown out of
// all contexts, the reserved words not counted.
func (a *App) argHeading() string {
	shown := 0
	for _, s := range a.suggestions.Args {
		if s.Value != contextcmd.WordPrevious && s.Value != contextcmd.WordNew {
			shown++
		}
	}
	return fmt.Sprintf("Contexts · %d of %d", shown, len(a.snapshot().Names))
}

// argRows renders the argument suggestions as list rows.
func (a *App) argRows() []cmdsuggest.Row {
	rows := make([]cmdsuggest.Row, len(a.suggestions.Args))
	for i := range a.suggestions.Args {
		s := a.suggestions.Args[i]
		rows[i] = cmdsuggest.Row{Arg: &s, Current: s.Current}
	}
	return rows
}

// argEmpty is the message of an argument list with no rows.
func (a *App) argEmpty() string {
	prefix := a.ctxArgText()
	if strings.HasPrefix(strings.ToLower(prefix), contextcmd.WordNew+" ") {
		return ""
	}
	return fmt.Sprintf("No context starts with %q", prefix)
}

// highlightedArg returns the value of the highlighted argument row, or "".
func (a *App) highlightedArg() string {
	if !a.argStage() || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Args) {
		return ""
	}
	return a.suggestions.Args[a.sugCursor].Value
}

// completeArg is tab at the argument stage: it highlights the first row when
// none is, otherwise writes the highlighted value into the line.
func (a *App) completeArg() {
	if len(a.suggestions.Args) == 0 {
		return
	}
	if a.sugCursor < 0 {
		a.sugCursor = a.sugOffset
		return
	}
	word, _, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
	text := word + " " + a.highlightedArg()
	if a.highlightedArg() == contextcmd.WordNew {
		text += " "
	}
	a.commandInput.SetValue(text)
	a.commandInput.CursorEnd()
	a.refreshSuggestions()
}

// runContext is enter on a :ctx command line.
func (a *App) runContext(args []string) (tea.Model, tea.Cmd) {
	highlighted := a.highlightedArg()
	if len(args) == 0 && highlighted != "" {
		args = []string{highlighted}
	}
	action := contextcmd.Resolve(args, highlighted, a.snapshot())
	if action.Kind == contextcmd.KeepOpen {
		a.sugNotice = action.Text
		return a, nil
	}
	a.closeCommandLineQuiet()
	switch action.Kind {
	case contextcmd.Switch:
		return a, a.switchContext(action.Name)
	case contextcmd.Create:
		return a, a.createContext(action.Name)
	case contextcmd.Refuse:
		return a, components.PostFooter(footerLevel(action.Level), action.Text)
	}
	return a, a.listContexts()
}

// closeCommandLineQuiet leaves command mode; the caller returns the Cmd that
// follows (the re-layout happens on the next resize).
func (a *App) closeCommandLineQuiet() {
	a.commandMode = false
	a.commandInput.Blur()
	a.resetSuggestions()
}

// footerLevel maps a contextcmd level to a footer level.
func footerLevel(l contextcmd.Level) components.Level {
	switch l {
	case contextcmd.Warn:
		return components.LevelWarning
	case contextcmd.Error:
		return components.LevelError
	}
	return components.LevelInfo
}

// createContext is the extension point for ":ctx new <name>".
// TODO(DEVDESK-116, step 7): create the context and switch to it. Until then
// it creates nothing.
func (a *App) createContext(_ string) tea.Cmd { return nil }
